#include <cstdio>
#include <iostream>
#include <cmath>
#include <cfloat>
using namespace std;

float absolute_value(float n){
    return n >= 0 ? n : -n;
}

int get_closest(int x, int y, int b){
    double target_ratio = (double)x / y;
    int low=0, high=1000000;
    for(int i=0; i<25; i++){
        int mid = (low + high) / 2;
        if ((double)mid / b < target_ratio)
            low = mid;
        else
            high = mid;
    }
    int best_a;
    double min_diff=DBL_MAX;
    for(int a=low-10; a<=high+10; a++){
        double diff = absolute_value((double)a / b - target_ratio);
        if (diff < min_diff){
            min_diff = diff;
            best_a = a;
        }
    }
    return best_a;
}

int main(){
    int x,y,n;
    scanf("%d %d %d",&x,&y,&n);
    int answer_a, answer_b;
    double smallest_difference=DBL_MAX;
    for(int b=1; b<=n; b++){
        int a = get_closest(x,y,b);
        double diff = absolute_value((double)a/b - (double)x/y);
        if (diff < smallest_difference){
            smallest_difference = diff;
            answer_a = a;
            answer_b = b;
        }
    }
    printf("%d/%d\n", answer_a, answer_b);
    return 0;
}
